(() => {
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={},owner;
const course=()=>window.BoraCourses[0];
const complete=(u,l)=>window.BoraBeginner?window.BoraBeginner.complete(u,l):!!u.courseProgress?.['pt/'+l.id]?.done;
function layout(ids){const points=ids.map(id=>({id,anchor:window.BoraMapData.places[id]?.point||[300,300],point:[...(window.BoraMapData.places[id]?.point||[300,300])]}));for(let n=0;n<100;n++)for(let i=0;i<points.length;i++)for(let j=i+1;j<points.length;j++){let a=points[i].point,b=points[j].point,dx=b[0]-a[0],dy=b[1]-a[1],d=Math.hypot(dx,dy);if(d<108){if(d<.01){dx=1;dy=i%2?1:-1;d=Math.SQRT2}const push=(108-d)/2+.1;for(const [p,sign] of [[a,-1],[b,1]]){p[0]=Math.max(40,Math.min(560,p[0]+sign*dx/d*push));p[1]=Math.max(40,Math.min(560,p[1]+sign*dy/d*push));}}}return points;}
function model(u,s={}){const c=course(),next=window.BoraStudy?.next(u)||c.lessons[0];let module=Number.isInteger(s.module)&&c.modules[s.module]?s.module:c.modules.findIndex(m=>m.lessons.includes(next.id));if(module<0)module=0;const ids=c.modules[module].lessons,selected=ids.includes(s.selected)?s.selected:ids.includes(next.id)?next.id:ids[0];return {module,selected,lessons:ids.map(id=>c.lessons.find(l=>l.id===id)).filter(Boolean),done:c.lessons.filter(l=>complete(u,l)).length,total:c.lessons.length,next:next.id};}
function reduce(s,a){return a.type==='module'?{module:Number(a.value)}:a.type==='select'?{...s,selected:a.value}:s;}
function home(u){if(owner!==u){owner=u;state={};window.BoraExplore?.reset()}const m=model(u,state);state={module:m.module,selected:m.selected};const c=course(),l=c.lessons.find(l=>l.id===m.selected),photo=window.BoraLessonPhotos[l.id],points=layout(m.lessons.map(x=>x.id)),done=complete(u,l),g=u.courseProgress?.['pt/'+l.id]?.guided,active=g&&!g.finishedAt&&(!l.beginnerVersion||g.version===l.beginnerVersion),status=done?'Пройдено':active?'Начато':'Впереди';const pin=(p,i)=>{const lesson=m.lessons[i],isDone=complete(u,lesson);return '<button type="button" class="atlas-pin '+(isDone?'is-done ':'')+(lesson.id===l.id?'is-selected':'')+'" data-stop="'+esc(lesson.id)+'" style="left:'+p.point[0]/6+'%;top:'+p.point[1]/6+'%" aria-pressed="'+(lesson.id===l.id)+'" aria-label="'+esc((i+1)+'. '+lesson.title+'. '+(window.BoraLessonPhotos[lesson.id]?.place||'Бразилия')+'. '+(isDone?'Пройдено':'Выбрать занятие'))+'"><span>'+(isDone?'✓':i+1)+'</span></button>'};return '<section class="journey"><div class="journey-heading"><div><h1>Твоя Бразилия.<br><span>По одному разговору.</span></h1><p>'+esc(u.name||'Привет')+', выбери остановку и начни занятие.</p></div><a class="journey-progress" href="#progress"><strong>'+m.done+' <span>/ '+m.total+'</span></strong><span>занятий пройдено</span><progress value="'+m.done+'" max="'+m.total+'">'+m.done+'</progress></a></div><div class="journey-toolbar"><label for="journey-module">Твой маршрут<select id="journey-module">'+c.modules.map((x,i)=>'<option value="'+i+'" '+(i===m.module?'selected':'')+'>'+esc(x.title)+'</option>').join('')+'</select></label><div class="journey-toolbar-links">'+(l.id!==m.next?'<button type="button" data-journey-resume>К моему занятию</button>':'')+'<a href="#courses/pt">Все занятия →</a></div></div><div class="atlas-workspace">'+(window.BoraExplore?window.BoraExplore.panel(m,points,pin):'<div class="atlas-map-panel"><div class="atlas-map" aria-label="Учебные остановки на карте Бразилии"><svg viewBox="0 0 600 600" aria-hidden="true"><path class="atlas-country" d="'+window.BoraMapData.path+'"/><path class="atlas-route" d="M'+points.map(p=>p.point.join(',')).join(' L')+'"/>'+points.map(p=>'<path class="atlas-leader" d="M'+p.anchor.join(',')+' L'+p.point.join(',')+'"/><circle class="atlas-location" cx="'+p.anchor[0]+'" cy="'+p.anchor[1]+'" r="3"/>').join('')+'<text x="66" y="280" class="atlas-country-name">BRASIL</text><text x="440" y="500" class="atlas-ocean">АТЛАНТИКА</text></svg>'+points.map(pin).join('')+'</div><div class="atlas-map-key"><span><i class="key-done"></i>Пройдено</span><span><i class="key-selected"></i>Выбрано</span><span>Карта учебного маршрута</span></div></div>')+(window.BoraExplore?.city()?window.BoraExplore.card():'<article class="journey-stop" aria-labelledby="journey-title"><div class="journey-photo"><img src="'+esc(photo?.src||'/assets/rio-panorama.webp')+'" alt="'+esc(photo?.place||'Бразилия')+'" width="640" height="360"><span>'+esc(photo?.place||'Бразилия')+'</span></div><div class="journey-stop-body"><div class="journey-stop-status '+(done?'is-done':'')+'">'+(done?'✓ ':'')+status+' · Занятие '+(c.lessons.indexOf(l)+1)+'</div><h2 id="journey-title">'+esc(l.title)+'</h2><p>'+esc(l.scene||l.topic||'Первые слова, понятные объяснения и практика шаг за шагом.')+'</p><button type="button" class="btn journey-start" data-journey-start="'+esc(l.id)+'">'+(done?'Повторить занятие':active?'Продолжить занятие':'Начать занятие')+' →</button><a class="journey-outline" href="#unit/'+esc(l.id)+'">Что будет в занятии</a><a class="journey-outline" href="#review/pt/'+esc(l.id)+'">Короткая тренировка</a></div></article>')+'</div>'+(window.BoraDrill?.recommendation(u)||'')+'<section class="journey-stops" aria-label="Занятия выбранного раздела"><h2>'+esc(c.modules[m.module].title)+'</h2><ol>'+m.lessons.map((x,i)=>'<li><button type="button" data-stop="'+esc(x.id)+'" aria-pressed="'+(x.id===l.id)+'" class="'+(complete(u,x)?'is-done':'')+'"><span class="stop-number">'+(complete(u,x)?'✓':i+1)+'</span><span><strong>'+esc(x.title)+'</strong><small>'+esc(window.BoraLessonPhotos[x.id]?.place||'Бразилия')+'</small></span><span class="stop-action">'+(x.id===l.id?'Выбрано':'→')+'</span></button></li>').join('')+'</ol></section></section>';}
function bind(u,save,render){if(!document.querySelector('.journey'))return;const redraw=(a,selector)=>{state=reduce(state,a);render();document.querySelector(selector)?.focus({preventScroll:true})};document.querySelector('#journey-module').onchange=e=>redraw({type:'module',value:e.target.value},'#journey-module');document.querySelector('[data-journey-resume]')?.addEventListener('click',()=>{state={};render();document.querySelector('[data-journey-start]')?.focus({preventScroll:true})});document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=e=>{const area=b.closest('.atlas-map')?'.atlas-map':'.journey-stops';redraw({type:'select',value:b.dataset.stop},area+' [data-stop="'+b.dataset.stop+'"]');if(e.detail>0&&window.matchMedia?.('(max-width:760px)').matches){document.querySelector('.journey-stop')?.scrollIntoView({block:'start',behavior:'instant'});document.querySelector('[data-journey-start]')?.focus({preventScroll:true});}});const begin=document.querySelector('[data-journey-start]');if(begin)begin.onclick=()=>{const id=model(u,state).selected;u.currentLesson=id;u.learningPath={lesson:id,reason:'journey-choice',at:new Date().toISOString()};save();location.hash='courses/pt/'+id;};window.BoraExplore?.bind(render);}
window.BoraJourney={home,bind,model,reduce,layout};
})();
